import{_ as e,o as n,c as i,a2 as t}from"./chunks/framework.DtFGJNng.js";const g=JSON.parse('{"title":"Alur berpikir","description":"","frontmatter":{},"headers":[],"relativePath":"alur-berpikir.md","filePath":"alur-berpikir.md","lastUpdated":1794463556000}'),d={name:"alur-berpikir.md"};function r(s,a,u,l,k,p){return n(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="alur-berpikir" tabindex="-1">Alur berpikir <a class="header-anchor" href="#alur-berpikir" aria-label="Permalink to &quot;Alur berpikir&quot;">​</a></h1><p>Halaman ini menjelaskan <em>kenapa</em> deuz dibuat seperti sekarang. Kalau kamu hanya ingin memakainya, mulai dari <a href="./memulai">Memulai</a>. Alasan per keputusan ada di <a href="./decisions">Keputusan desain</a>.</p><h2 id="masalah-yang-ingin-diselesaikan" tabindex="-1">Masalah yang ingin diselesaikan <a class="header-anchor" href="#masalah-yang-ingin-diselesaikan" aria-label="Permalink to &quot;Masalah yang ingin diselesaikan&quot;">​</a></h2><p>Saat bekerja dengan AI agent, kita cenderung langsung meminta: &quot;buatkan fitur pemesanan buku&quot;. Agent akan mengisi sendiri semua hal yang tidak kita sebut. Hasilnya bisa jalan, tapi belum tentu sesuai maksud. Alasan di balik keputusannya juga hilang begitu percakapan ditutup.</p><p>Di tim, masalahnya bertambah. Kerja ulang paling sering terjadi <strong>di titik serah terima</strong>:</p><ul><li>layar dibuat dari spec yang belum selesai;</li><li>frontend menebak bentuk API karena kontraknya belum disepakati;</li><li>QA menulis test dari ingatan, bukan dari aturan yang tertulis;</li><li>dokumen perencanaan (spreadsheet, PRD) membeku setelah rilis, sehingga tidak ada yang tahu &quot;aturan sekarang sebenarnya bagaimana&quot;.</li></ul><h2 id="jawabannya-spec-driven-development" tabindex="-1">Jawabannya: spec-driven development <a class="header-anchor" href="#jawabannya-spec-driven-development" aria-label="Permalink to &quot;Jawabannya: spec-driven development&quot;">​</a></h2><p><strong>Sepakati dulu perilaku yang diinginkan secara tertulis, baru dibangun, lalu perbarui dokumen &quot;keadaan sekarang&quot;.</strong> Dokumen itu yang menjadi acuan, bukan isi chat atau ingatan.</p><p>deuz mengambil gagasan ini dari <a href="https://github.com/Fission-AI/OpenSpec" target="_blank" rel="noreferrer">OpenSpec</a>, lalu menyesuaikannya untuk tim dengan beberapa peran.</p><h2 id="prinsip-yang-dipegang-deuz" tabindex="-1">Prinsip yang dipegang deuz <a class="header-anchor" href="#prinsip-yang-dipegang-deuz" aria-label="Permalink to &quot;Prinsip yang dipegang deuz&quot;">​</a></h2><h3 id="_1-yang-sudah-dibangun-dipisah-dari-yang-sedang-direncanakan" tabindex="-1">1. Yang sudah dibangun dipisah dari yang sedang direncanakan <a class="header-anchor" href="#_1-yang-sudah-dibangun-dipisah-dari-yang-sedang-direncanakan" aria-label="Permalink to &quot;1. Yang sudah dibangun dipisah dari yang sedang direncanakan&quot;">​</a></h3><p>Homes (<code>deuz/specs/</code>, file desain, definisi API) hanya berisi yang sudah ada di kode. Rencana tinggal di work sampai selesai. Karena itu homes selalu bisa dipercaya. Spec yang isinya tidak sesuai kode lama-lama tidak akan dibaca orang.</p><h3 id="_2-tulis-yang-berubah-saja-delta" tabindex="-1">2. Tulis yang berubah saja (delta) <a class="header-anchor" href="#_2-tulis-yang-berubah-saja-delta" aria-label="Permalink to &quot;2. Tulis yang berubah saja (delta)&quot;">​</a></h3><p>Sebagian besar pekerjaan mengubah sistem yang sudah ada. Delta (<code>ADDED</code>, <code>MODIFIED</code>, <code>REMOVED</code>, <code>RENAMED</code>) membuat perubahan bisa direview tanpa membaca ulang seluruh sistem. Spec permanen tumbuh sedikit demi sedikit lewat archive, jadi tidak perlu ditulis lengkap di awal.</p><h3 id="_3-setiap-dokumen-punya-pemilik-dan-selesai-harus-dikonfirmasi" tabindex="-1">3. Setiap dokumen punya pemilik, dan &quot;selesai&quot; harus dikonfirmasi <a class="header-anchor" href="#_3-setiap-dokumen-punya-pemilik-dan-selesai-harus-dikonfirmasi" aria-label="Permalink to &quot;3. Setiap dokumen punya pemilik, dan &quot;selesai&quot; harus dikonfirmasi&quot;">​</a></h3><p>Di OpenSpec, satu orang menulis semua dokumen, jadi dokumen dianggap selesai begitu filenya ada. Di tim, dokumen yang filenya sudah ada belum tentu siap dipakai peran berikutnya. Maka setiap artifact punya pemilik, dan statusnya baru <code>ready</code> setelah pemiliknya menyatakan selesai. Bagi peran berikutnya, inilah sinyal untuk mulai.</p><h3 id="_4-urutan-dokumen-mengikuti-ketergantungan-antar-peran" tabindex="-1">4. Urutan dokumen mengikuti ketergantungan antar peran <a class="header-anchor" href="#_4-urutan-dokumen-mengikuti-ketergantungan-antar-peran" aria-label="Permalink to &quot;4. Urutan dokumen mengikuti ketergantungan antar peran&quot;">​</a></h3><p>Bentuk API mengikuti apa yang harus ditampilkan dan dilakukan layar, jadi kontrak ditulis setelah desain. Setelah kontrak disepakati backend dan frontend, backend, frontend, dan QA bisa bekerja paralel tanpa saling menunggu. Inilah hasil yang dicari: kesepakatan di depan supaya kerja di belakang bisa paralel.</p><h3 id="_5-satu-alur-ukurannya-menyesuaikan" tabindex="-1">5. Satu alur, ukurannya menyesuaikan <a class="header-anchor" href="#_5-satu-alur-ukurannya-menyesuaikan" aria-label="Permalink to &quot;5. Satu alur, ukurannya menyesuaikan&quot;">​</a></h3><p>Bug fix tidak boleh menunggu rapat, sedangkan fitur harus disetujui. deuz tidak membuat dua alur. Ia memakai satu template, dan artifact yang tidak relevan di-skip berdasarkan checklist di proposal. Hasilnya, proposal fitur bisa dua halaman, sedangkan proposal bug fix cukup sepuluh baris.</p><h3 id="_6-aturan-dijalankan-program-isi-ditulis-ai" tabindex="-1">6. Aturan dijalankan program, isi ditulis AI <a class="header-anchor" href="#_6-aturan-dijalankan-program-isi-ditulis-ai" aria-label="Permalink to &quot;6. Aturan dijalankan program, isi ditulis AI&quot;">​</a></h3><p>Menulis isi dokumen butuh penilaian, jadi diserahkan ke agent. Menghitung status, mengunci artifact, memeriksa format, dan menggabungkan delta adalah aturan, jadi dijalankan CLI. Hasilnya sama persis di agent mana pun dan bagi siapa pun.</p><h3 id="_7-bisnis-bicara-lewat-dokumen-yang-bisa-mereka-baca" tabindex="-1">7. Bisnis bicara lewat dokumen yang bisa mereka baca <a class="header-anchor" href="#_7-bisnis-bicara-lewat-dokumen-yang-bisa-mereka-baca" aria-label="Permalink to &quot;7. Bisnis bicara lewat dokumen yang bisa mereka baca&quot;">​</a></h3><p>Proposal dimulai dengan bagian bisnis yang bisa dipresentasikan apa adanya. Aturan bisnis ditulis <strong>hanya sekali</strong>, di spec, dalam bahasa bisnis. Proposal cukup menunjuk aturan mana yang perlu disetujui. Dengan begitu tidak ada dua salinan aturan yang lama-lama berbeda isi.</p><h2 id="kapan-deuz-tidak-cocok" tabindex="-1">Kapan deuz tidak cocok <a class="header-anchor" href="#kapan-deuz-tidak-cocok" aria-label="Permalink to &quot;Kapan deuz tidak cocok&quot;">​</a></h2><ul><li><strong>Eksperimen dan prototype sekali pakai.</strong> Tujuannya belajar cepat, bukan menyepakati perilaku.</li><li><strong>Perubahan sangat kecil yang tidak mengubah perilaku</strong>, seperti typo atau upgrade dependency kecil. Jalur engineer bisa dipakai, tapi kalau tim sepakat perubahan semacam itu tidak perlu work, itu juga wajar.</li></ul><h2 id="hubungan-dengan-cara-kerja-lain" tabindex="-1">Hubungan dengan cara kerja lain <a class="header-anchor" href="#hubungan-dengan-cara-kerja-lain" aria-label="Permalink to &quot;Hubungan dengan cara kerja lain&quot;">​</a></h2><p>deuz tidak menggantikan praktik lain, tapi bekerja di lapisan yang berbeda:</p><table tabindex="0"><thead><tr><th>Praktik</th><th>Hubungannya dengan deuz</th></tr></thead><tbody><tr><td>BDD (Given/When/Then)</td><td>Format scenario di spec diambil dari sini</td></tr><tr><td>TDD</td><td>Setiap scenario adalah kandidat test. QA memetakannya di <code>tasks-test</code></td></tr><tr><td>API-first / contract-first</td><td><code>api-contract</code> adalah bentuk formalnya, lalu dipromote ke definisi API (misalnya OpenAPI)</td></tr><tr><td>Code review lewat pull request</td><td>Tetap di luar deuz. deuz hanya mencatat keputusan &quot;sudah siap&quot;</td></tr></tbody></table><h2 id="bedanya-dengan-openspec-singkatnya" tabindex="-1">Bedanya dengan OpenSpec, singkatnya <a class="header-anchor" href="#bedanya-dengan-openspec-singkatnya" aria-label="Permalink to &quot;Bedanya dengan OpenSpec, singkatnya&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>OpenSpec</th><th>deuz</th></tr></thead><tbody><tr><td>Penulis</td><td>Satu orang dengan AI</td><td>Beberapa peran dengan serah terima</td></tr><tr><td>Tanda selesai</td><td>File ada</td><td>Dikonfirmasi pemilik, dengan hash</td></tr><tr><td>Urutan</td><td>proposal → specs, design → tasks</td><td>proposal → specs → ui-design → api-contract → tasks per peran</td></tr><tr><td>Desain teknis</td><td><code>design.md</code></td><td>Bagian <em>Technical decisions</em> di tiap tasks</td></tr><tr><td>Kontrak API</td><td>Tidak ada</td><td><code>api-contract</code> milik backend dan frontend</td></tr><tr><td>Persetujuan bisnis</td><td>Tidak dimodelkan</td><td>Role <code>business</code> opsional, Gate 1 dan Gate 2</td></tr><tr><td>Aturan</td><td>CLI TypeScript</td><td>CLI Go satu binary</td></tr></tbody></table><p>Daftar lengkapnya, beserta alasan tiap perbedaan, ada di <a href="./decisions">Keputusan desain</a>.</p>',32)])])}const m=e(d,[["render",r]]);export{g as __pageData,m as default};
